import type { Component } from '@vesk/types';
import { LoadingIndicator } from '@vesk/runtime/router'

interface NavItem {
	label: string
	href: string
}

interface LayoutProps {
	children?: Component
}

const navItems: NavItem[] = [
	{ label: 'Home', href: '/' },
	{ label: 'About', href: '/about' },
	{ label: 'Blog', href: '/blog' },
	{ label: 'Posts', href: '/posts' },
	{ label: 'Statements', href: '/statements' },
	{ label: 'GuardTest', href: '/guardtest' },
	{ label: 'Async', href: '/async' },
	{ label: 'Map', href: '/map' },
	{ label: 'Empty', href: '/empty' },
	{ label: 'Md', href: '/md' },
	{ label: 'Md HTML', href: '/md-html' },
	{ label: 'Broken', href: '/broken' },
	{ label: 'StandaloneDep', href: '/standalonedep' },
	{ label: 'Portal', href: '/portal' },
	{ label: 'StoreApi', href: '/store-api' },
]

component Layout(props: LayoutProps) {
	<Head>
	<link rel="shortcut icon" href="/favicon.svg" type="image/x-icon">
	</Head>
	<LoadingIndicator height={3} throttle={0} duration={1500} />
	<nav class="flex nav gap-6 px-8 py-4 border-b border-gray-200 bg-white">
		for (const item of navItems) {
			<NavLink href={item.href} class="text-gray-500 hover:text-black font-medium no-underline">{item.label}</NavLink>
		}
	</nav>
	<style> 
	.nav {
		margin-left: 20px;
		display: flex;
		gap: 10px;
	}
	</style>
	<main class="max-w-3xl mx-auto my-8 px-4">{props.children}</main>
	<footer class="text-center py-8 text-gray-400 text-sm">
		<p>Powered by Vesk</p>
	</footer>
}

